import React from 'react';

export interface StatItem {
  value: string | number;
  label: string;
  accent?: boolean;
}

export interface StatGridProps {
  stats: StatItem[];
  className?: string;
}

export const StatGrid: React.FC<StatGridProps> = ({ stats, className = '' }) => {
  return (
    <div className={`grid-stats ${className}`}>
      {stats.map((stat, idx) => (
        <div key={idx} className="stat-card">
          <div className={`stat-value ${stat.accent ? 'stat-value-accent' : ''}`}>
            {stat.value}
          </div>
          <div className="stat-label">
            {stat.label}
          </div>
        </div>
      ))}
    </div>
  );
};
