import React from 'react';
import type { WebsiteEvent } from '../../types/index.js';
import { formatEventDateLong, formatEventDescription } from '../../config/events.js';
import { downloadEventIcs } from '../../utils/calendar.js';
import { EventStatusBadge } from './EventStatusBadge.js';
import { EventShareButton } from './EventShareButton.js';

export interface ActiveEventCardProps {
  event: WebsiteEvent;
  onNavigate?: (path: string, e?: React.MouseEvent) => void;
  showDetailsButton?: boolean;
  className?: string;
}

export const ActiveEventCard: React.FC<ActiveEventCardProps> = ({
  event,
  onNavigate,
  showDetailsButton = false,
  className = ''
}) => {
  return (
    <div id={event.slug} className={`card card-accent-primary ${className}`}>
      {/* Top Badges & Share Row */}
      <div className="event-card-top-row">
        <div className="flex-row flex-wrap gap-2">
          <EventStatusBadge status={event.status} />
          {event.category && (
            <span className="badge badge-secondary">{event.category}</span>
          )}
        </div>
        <EventShareButton event={event} />
      </div>


      <h3 className="event-title mb-1">{event.title}</h3>
      {event.subtitle && (
        <div className="event-subtitle mb-2">
          {event.subtitle}
        </div>
      )}

      {/* Prominent Schedule & Location Bar */}
      <div className="event-schedule-bar">
        <div className="event-schedule-item event-schedule-date">
          <span className="event-schedule-icon">📅</span>
          <span>{formatEventDateLong(event.date)}</span>
        </div>
        {event.timeLabel && (
          <div className="event-schedule-item event-schedule-time">
            <span className="event-schedule-icon">🕒</span>
            <span>{event.timeLabel}</span>
          </div>
        )}
        {event.location && (
          <div className="event-schedule-item event-location-tag">
            <span className="event-schedule-icon">📍</span>
            <span>{event.location}</span>
          </div>
        )}
      </div>

      {/* Responsive Content Grid: Stacks on mobile, 2 columns on tablet/desktop */}
      <div className={event.image ? 'event-card-grid' : ''}>
        <div>
          {/* HTML & Marker rendered Description */}
          <div
            className="event-desc-formatted mb-4"
            dangerouslySetInnerHTML={{ __html: formatEventDescription(event.description) }}
          />

          {/* Featured Panelists */}
          {event.panelists && event.panelists.length > 0 && (
            <div className="event-panelists-section mb-4">
              <strong>Featured Panelists:</strong>
              <div className="event-panelists-list">
                {event.panelists.map((panelist, idx) => (
                  <a
                    key={idx}
                    href={panelist.url || '#'}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="card-subtle panelist-badge"
                  >
                    {panelist.name} ↗
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="event-actions">
            {event.url && event.url.startsWith('http') ? (
              <a
                href={event.url}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-primary"
              >
                Register on Zoom ↗
              </a>
            ) : (
              <span className="badge badge-warning">Registration Opening Soon</span>
            )}

            <button
              type="button"
              onClick={() => downloadEventIcs(event)}
              className="btn btn-outline"
              title="Download iCalendar file (.ics) to import into Google Calendar, Apple Calendar, or Outlook"
            >
              📅 Add to Calendar (.ics)
            </button>

            {showDetailsButton && onNavigate && (
              <button
                type="button"
                onClick={(e) => onNavigate('/events', e)}
                className="btn btn-outline"
              >
                Event Details
              </button>
            )}
          </div>
        </div>

        {/* Flyer Image */}
        {event.image && (
          <div className="event-flyer-wrap">
            <img
              src={event.image}
              alt={event.title}
              className="event-flyer-img"
            />
          </div>
        )}
      </div>
    </div>
  );
};
