import type { RouteDefinition } from '../routes/types.js';

const SITE_NAME = 'CEGAANA';
const DEFAULT_TITLE = 'CEGAANA | College of Engineering Guindy Alumni Association of North America';
const DEFAULT_DESCRIPTION = 'Official website of the College of Engineering Guindy Alumni Association of North America (CEGAANA) - connecting alumni, supporting student betterment, and hosting global conferences.';
const DEFAULT_IMAGE = 'https://cegaana.github.io/cegaana_logo.jpg';
const SITE_URL = 'https://cegaana.github.io';

/**
 * Sets or creates a meta tag in document.head
 */
function setMetaTag(selector: string, attribute: string, value: string): void {
  let element = document.querySelector(selector) as HTMLMetaElement | null;
  if (!element) {
    element = document.createElement('meta');
    if (selector.startsWith('meta[name=')) {
      const name = selector.match(/meta\[name="([^"]+)"\]/)?.[1];
      if (name) element.setAttribute('name', name);
    } else if (selector.startsWith('meta[property=')) {
      const property = selector.match(/meta\[property="([^"]+)"\]/)?.[1];
      if (property) element.setAttribute('property', property);
    }
    document.head.appendChild(element);
  }
  element.setAttribute(attribute, value);
}

/**
 * Sets or creates the canonical link tag in document.head
 */
function setCanonical(url: string): void {
  let link = document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
  if (!link) {
    link = document.createElement('link');
    link.setAttribute('rel', 'canonical');
    document.head.appendChild(link);
  }
  link.setAttribute('href', url);
}

/**
 * Dynamically updates document title, standard meta description,
 * Open Graph (og:*) tags, Twitter card tags, and canonical link
 * based on current route metadata.
 */
export function updatePageSeo(route?: RouteDefinition, currentPath: string = '/'): void {
  const title = route?.title || DEFAULT_TITLE;
  const description = route?.description || DEFAULT_DESCRIPTION;
  const ogImage = route?.ogImage || DEFAULT_IMAGE;
  const ogType = route?.ogType || 'website';
  const cleanPath = currentPath.startsWith('/') ? currentPath : `/${currentPath}`;
  const canonicalUrl = `${SITE_URL}${cleanPath === '/' ? '' : cleanPath}`;

  // 1. Document title
  document.title = title;

  // 2. Standard Meta Description
  setMetaTag('meta[name="description"]', 'content', description);

  // 3. Open Graph Tags
  setMetaTag('meta[property="og:site_name"]', 'content', SITE_NAME);
  setMetaTag('meta[property="og:title"]', 'content', title);
  setMetaTag('meta[property="og:description"]', 'content', description);
  setMetaTag('meta[property="og:image"]', 'content', ogImage);
  setMetaTag('meta[property="og:url"]', 'content', canonicalUrl);
  setMetaTag('meta[property="og:type"]', 'content', ogType);

  // 4. Twitter Card Meta Tags
  setMetaTag('meta[name="twitter:card"]', 'content', 'summary_large_image');
  setMetaTag('meta[name="twitter:title"]', 'content', title);
  setMetaTag('meta[name="twitter:description"]', 'content', description);
  setMetaTag('meta[name="twitter:image"]', 'content', ogImage);

  // 5. Canonical Link
  setCanonical(canonicalUrl);
}
