/**
 * Events Catalog Configuration & Lifecycle Status
 *
 * Events are loaded directly from the canonical JSON data source (../data/events.json),
 * synchronized from tools/marketing-site/events/events_list.json.
 * Dynamic registration state is computed at runtime based on event lifecycle
 * status and environment feature flags.
 */

import type { WebsiteEvent } from '../types/index.js';
export type { WebsiteEvent };
import rawEventsData from '../data/events.json';
import { isEventRegistrationOpen } from './features.js';

export function formatEventDate(dateStr: string): string {
  if (!dateStr) return '';
  if (dateStr.includes('T')) {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime())) {
      return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
    }
  }
  return dateStr;
}

export function formatEventDateLong(dateStr: string): string {
  if (!dateStr) return '';
  if (dateStr.includes('T') || dateStr.includes('-')) {
    const d = new Date(dateStr);
    if (!isNaN(d.getTime())) {
      return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });
    }
  }
  return dateStr;
}

export function formatEventDescription(desc: string): string {
  if (!desc) return '';
  // If HTML tags like <br>, <p>, <div> are present, return as is
  if (/<(br|p|div|ul|ol|li)[^>]*>/i.test(desc)) {
    return desc;
  }
  // Convert double newlines to paragraphs and single newlines to <br/>
  if (desc.includes('\n')) {
    return desc
      .split(/\n\n+/)
      .map(p => `<p>${p.replace(/\n/g, '<br/>')}</p>`)
      .join('');
  }
  return desc;
}



// Hydrate raw JSON event records with dynamic runtime registration flags
export const websiteEvents: WebsiteEvent[] = (rawEventsData as unknown as Omit<WebsiteEvent, 'registrationOpen'>[]).map(event => ({
  ...event,
  registrationOpen: event.status === 'completed'
    ? isEventRegistrationOpen(event.slug)
    : (event.status === 'active' || isEventRegistrationOpen(event.slug))
}));

export function getEventBySlug(slug: string): WebsiteEvent | undefined {
  return websiteEvents.find(e => e.slug === slug || String(e.id) === slug);
}

export function getActiveEvents(): WebsiteEvent[] {
  return websiteEvents.filter(e => e.status === 'active' || e.status === 'upcoming');
}

export function getCompletedEvents(): WebsiteEvent[] {
  return websiteEvents.filter(e => e.status === 'completed');
}
