import rawBlogData from './blog.json';

export interface BlogPost {
  id: string;
  slug: string;
  badge: string;
  title: string;
  date: string;
  author: string;
  category: string;
  description: string;
  path: string;
}

export const blogPosts: BlogPost[] = rawBlogData as unknown as BlogPost[];

export function getBlogPostBySlug(slug: string): BlogPost | undefined {
  return blogPosts.find(p => p.slug === slug || p.id === slug);
}

