import React, { useState } from 'react';
import { appConfig } from '../../config/env.js';

interface HeaderProps {
  onNavigate?: (path: string, e: React.MouseEvent) => void;
}

export const Header: React.FC<HeaderProps> = ({ onNavigate }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleLinkClick = (path: string, e: React.MouseEvent) => {
    if (onNavigate) {
      onNavigate(path, e);
    }
    setMobileMenuOpen(false);
  };

  return (
    <header className="site-header">
      <div className="container site-header-container">
        {/* Brand Logo */}
        <a href="/" onClick={(e) => handleLinkClick('/', e)} className="site-logo">
          <img src="/assets/cegaana_logo.jpg" alt="CEGAANA" />
        </a>

        {/* Desktop Navigation */}
        <nav className="desktop-nav">
          <a href="/" onClick={(e) => handleLinkClick('/', e)} className="nav-link">Home</a>
          <a href="/events" onClick={(e) => handleLinkClick('/events', e)} className="nav-link">Events</a>
          <a href="/projects" onClick={(e) => handleLinkClick('/projects', e)} className="nav-link">Projects</a>
          <a href="/join" onClick={(e) => handleLinkClick('/join', e)} className="nav-link">Join</a>
          <a href="/blog" onClick={(e) => handleLinkClick('/blog', e)} className="nav-link">Blog</a>

          {/* Member Portal Link */}
          <a
            href={appConfig.membersPortalUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="nav-link nav-link-portal"
          >
            Members ↗
          </a>

          {/* Contribute Action */}
          <a
            href="/contribute"
            onClick={(e) => handleLinkClick('/contribute', e)}
            className="btn btn-primary btn-sm"
          >
            Contribute
          </a>
        </nav>

        {/* Mobile Hamburger Button */}
        <button
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          className="mobile-toggle"
          aria-label="Toggle navigation menu"
        >
          {mobileMenuOpen ? '✕' : '☰'}
        </button>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div className="mobile-drawer">
          <a href="/" onClick={(e) => handleLinkClick('/', e)} className="nav-link">Home</a>
          <a href="/events" onClick={(e) => handleLinkClick('/events', e)} className="nav-link">Events</a>
          <a href="/projects" onClick={(e) => handleLinkClick('/projects', e)} className="nav-link">Projects</a>
          <a href="/join" onClick={(e) => handleLinkClick('/join', e)} className="nav-link">Join</a>
          <a href="/blog" onClick={(e) => handleLinkClick('/blog', e)} className="nav-link">Blog</a>
          <a
            href={appConfig.membersPortalUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="nav-link"
          >
            Member Portal ↗
          </a>
          <a
            href="/contribute"
            onClick={(e) => handleLinkClick('/contribute', e)}
            className="btn btn-primary btn-full"
            style={{ marginTop: '0.5rem' }}
          >
            Contribute
          </a>
        </div>
      )}
    </header>
  );
};
