import { BlogPage } from '../pages/BlogPage.js';
import { BlogElections2026Page } from '../pages/BlogElections2026Page.js';
import type { RouteDefinition } from './types.js';

/**
 * Sub-routes for the /blog section.
 * Keys are relative to the `/blog` prefix (e.g. '' for /blog, '2026-elections' for /blog/2026-elections).
 */
export const blogSubRoutes: Record<string, RouteDefinition> = {
  '': {
    component: BlogPage,
    title: 'Blog & Announcements | CEGAANA',
    description: 'Official news, community stories, conference recaps, and board governance announcements from the CEGAANA alumni community.',
    ogType: 'website',
  },
  '2026-elections': {
    component: BlogElections2026Page,
    title: 'CEGAANA 2026 Board Elections | Official Announcement',
    description: 'Official announcement, key dates, nomination procedures, and voter guidelines for the CEGAANA 2026 Board of Directors elections.',
    ogType: 'article',
  },
};


/**
 * Resolve a sub-path within the /blog domain.
 * @param subPath The path relative to /blog, with leading/trailing slashes trimmed.
 */
export function resolveBlogRoute(subPath: string): RouteDefinition | undefined {
  return blogSubRoutes[subPath];
}
