import type { RouteDefinition } from './types.js';
import { coreRoutes } from './coreRoutes.js';
import { givingRoutes } from './givingRoutes.js';
import { resolveBlogRoute } from './blogRoutes.js';
import { resolveConvergeRoute } from './convergeRoutes.js';

export * from './types.js';
export * from './coreRoutes.js';
export * from './givingRoutes.js';
export * from './blogRoutes.js';
export * from './convergeRoutes.js';

/**
 * Normalizes URL pathnames:
 * - Strips query parameters and hashes
 * - Strips `/index.html` and `.html` extensions
 * - Strips redundant trailing slashes
 */
export function normalizePath(rawPath: string): string {
  if (!rawPath) return '/';
  let clean = rawPath.split('?')[0].split('#')[0];
  clean = clean.replace(/\/index\.html$/i, '');
  clean = clean.replace(/\.html$/i, '');
  clean = clean.replace(/\/+$/, '');
  return clean === '' ? '/' : clean;
}

/**
 * Resolves a URL pathname to its corresponding RouteDefinition using modular sub-route handlers.
 * @param rawPath The pathname to resolve (e.g., window.location.pathname)
 */
export function resolveRoute(rawPath: string): RouteDefinition | undefined {
  const path = normalizePath(rawPath);

  // 1. Core top-level routes
  if (coreRoutes[path]) {
    return coreRoutes[path];
  }

  // 2. Giving and contribution routes
  if (givingRoutes[path]) {
    return givingRoutes[path];
  }

  // 3. Blog domain sub-routes (/blog, /blog/2026-elections, etc.)
  if (path === '/blog' || path.startsWith('/blog/')) {
    const subPath = path === '/blog' ? '' : path.slice('/blog/'.length);
    const blogRoute = resolveBlogRoute(subPath);
    if (blogRoute) return blogRoute;
  }

  // 4. Converge domain sub-routes (/converge, /converge/2026, /converge/2026/lf, etc.)
  if (path === '/converge' || path.startsWith('/converge/')) {
    const subPath = path === '/converge' ? '' : path.slice('/converge/'.length);
    const convergeRoute = resolveConvergeRoute(subPath);
    if (convergeRoute) return convergeRoute;
  }


  return undefined;
}
