import React from 'react';

interface SectionHeaderProps {
  eyebrow?: string;
  title: string;
  subtitle?: string;
  align?: 'center' | 'left';
  maxWidth?: string;
  marginBottom?: string;
}

export const SectionHeader: React.FC<SectionHeaderProps> = ({
  eyebrow,
  title,
  subtitle,
  align = 'center',
  maxWidth,
  marginBottom
}) => {
  const isLeft = align === 'left';

  return (
    <div
      className={`section-header ${isLeft ? 'section-header-left' : ''}`}
      style={{
        maxWidth,
        marginBottom
      }}
    >
      {eyebrow && (
        <span className="section-eyebrow">
          {eyebrow}
        </span>
      )}
      <h2 className="section-title">
        {title}
      </h2>
      {subtitle && (
        <p className="section-subtitle">
          {subtitle}
        </p>
      )}
    </div>
  );
};
