/**
 * Environment Configuration for @cegaana/website
 * Reads Vite environment variables with type-safe defaults
 */

import pkg from '../../package.json';

export interface AppEnvConfig {
  version: string;
  appEnv: 'development' | 'staging' | 'production';
  isDevelopment: boolean;
  isStaging: boolean;
  isProduction: boolean;
  siteUrl: string;
  siteTitle: string;
  membersPortalUrl: string;
  showStagingBanner: boolean;
  robotsNoIndex: boolean;
  stripePublishableKey: string;
  gaMeasurementId: string;
}

const env = import.meta.env;

export const appConfig: AppEnvConfig = {
  version: pkg.version || '2.0.0',
  appEnv: (env.VITE_APP_ENV as 'development' | 'staging' | 'production') || 'development',
  isDevelopment: env.VITE_APP_ENV === 'development' || !env.VITE_APP_ENV,
  isStaging: env.VITE_APP_ENV === 'staging',
  isProduction: env.VITE_APP_ENV === 'production',
  siteUrl: env.VITE_SITE_URL || 'http://localhost:5181',
  siteTitle: env.VITE_SITE_TITLE || 'CEGAANA | College of Engineering Guindy Alumni Association of North America',
  membersPortalUrl: env.VITE_MEMBERS_PORTAL_URL || 'https://members.cegaana.org',
  showStagingBanner: env.VITE_SHOW_STAGING_BANNER === 'true' || env.VITE_APP_ENV === 'staging',
  robotsNoIndex: env.VITE_ROBOTS_NOINDEX === 'true' || env.VITE_APP_ENV === 'staging',
  stripePublishableKey: env.VITE_STRIPE_PUBLISHABLE_KEY || '',
  gaMeasurementId: env.VITE_GA_MEASUREMENT_ID || '',
};
