import React, { useEffect, useState } from 'react';
import type { PageProps } from './types.js';
import rawRedirects from '../data/redirects.json';

interface ExactRedirect {
  source: string;
  target: string;
  type: string;
  description?: string;
}

interface PrefixRedirect {
  prefix: string;
  targetBase: string;
  preserveSubpath?: boolean;
  preserveQuery?: boolean;
  description?: string;
}

interface RedirectsConfig {
  exactRedirects: ExactRedirect[];
  prefixRedirects: PrefixRedirect[];
}

const redirectsConfig = rawRedirects as RedirectsConfig;

export const NotFoundPage: React.FC<PageProps> = ({ onNavigate }) => {
  const [redirectTarget, setRedirectTarget] = useState<string | null>(null);

  useEffect(() => {
    const pathname = window.location.pathname;
    const search = window.location.search;
    const hash = window.location.hash;

    // 1. Check exact redirects
    const exactMatch = redirectsConfig.exactRedirects.find(r => r.source === pathname);
    if (exactMatch) {
      if (exactMatch.type === 'internal') {
        onNavigate(exactMatch.target);
        return;
      }
      setRedirectTarget(exactMatch.target);
      window.location.replace(exactMatch.target);
      return;
    }

    // 2. Check prefix redirects (e.g. legacy AlmaShines URLs)
    const prefixMatch = redirectsConfig.prefixRedirects.find(r =>
      pathname === r.prefix || pathname.startsWith(r.prefix + '/') || pathname.startsWith(r.prefix)
    );

    if (prefixMatch) {
      const fullTarget = `${prefixMatch.targetBase}${pathname}${search}${hash}`;
      setRedirectTarget(fullTarget);
      // Small timeout for smooth visual cue if connection takes a moment
      const timer = setTimeout(() => {
        window.location.replace(fullTarget);
      }, 350);
      return () => clearTimeout(timer);
    }
  }, [onNavigate]);

  if (redirectTarget) {
    return (
      <div className="section-page">
        <div className="container">
          <div className="redirect-card">
            <div className="redirect-spinner" />
            <h2 className="mb-2">Redirecting...</h2>
            <p className="text-muted mb-4">
              Taking you to the CEGAANA Member Portal. If you are not redirected automatically, please click below.
            </p>
            <a href={redirectTarget} className="btn btn-primary btn-sm">
              Continue to Member Portal →
            </a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="section-page">
      <div className="container">
        <div className="not-found-wrap">
          <div className="not-found-code">404</div>
          <h2 className="mb-2">Page Not Found</h2>
          <p className="not-found-desc">
            We could not find the page you were looking for. It may have been moved, renamed, or is temporarily unavailable.
          </p>
          <button
            onClick={(e) => onNavigate('/', e)}
            className="btn btn-primary"
          >
            Back to Home
          </button>
        </div>
      </div>
    </div>
  );
};
