import React from 'react';
import type { WebsiteEvent } from '../../types/index.js';
import { formatEventDate } from '../../config/events.js';

export interface CompletedEventCardProps {
  event: WebsiteEvent;
  onNavigate?: (path: string, e?: React.MouseEvent) => void;
  variant?: 'row' | 'card';
  className?: string;
}

export const CompletedEventCard: React.FC<CompletedEventCardProps> = ({
  event,
  onNavigate,
  variant = 'row',
  className = ''
}) => {
  const cleanDescription = event.description.replace(/<[^>]*>/g, '');
  const truncatedDescription = cleanDescription.length > 140
    ? `${cleanDescription.slice(0, 140)}...`
    : cleanDescription;

  if (variant === 'card') {
    return (
      <div id={event.slug} className={`card card-interactive completed-event-card ${className}`}>
        <div>
          <div className="flex-between mb-2">
            <span className="badge badge-completed badge-sm">Concluded</span>
            <span className="text-muted text-sm">{formatEventDate(event.date)}</span>
          </div>
          <h4 className="event-past-title mb-1">{event.title}</h4>
          <p className="event-past-desc">{truncatedDescription}</p>
        </div>

        <div className="mt-4">
          {event.recapUrl ? (
            <a href={event.recapUrl} className="btn btn-outline btn-sm btn-full">
              📸 View Event Recap
            </a>
          ) : onNavigate ? (
            <button
              onClick={(e) => onNavigate(event.url || '/events', e)}
              className="btn btn-outline btn-sm btn-full"
            >
              View Details
            </button>
          ) : null}
        </div>
      </div>
    );
  }

  // Default 'row' layout for EventsPage list
  return (
    <div id={event.slug} className={`card event-past-card flex-between flex-wrap gap-4 ${className}`}>
      <div className="flex-1">
        <div className="flex-row flex-wrap gap-2 mb-1">
          <h3 className="event-past-title">{event.title}</h3>
          {event.category && (
            <span className="badge badge-secondary badge-sm">
              {event.category}
            </span>
          )}
          <span className="badge badge-completed badge-sm">
            Concluded
          </span>
        </div>

        <div className="flex-row flex-wrap gap-4 text-muted text-sm mb-1">
          <span>📅 {formatEventDate(event.date)}</span>
          <span>📍 {event.location}</span>
        </div>

        <p className="event-past-desc">
          {truncatedDescription}
        </p>
      </div>

      {/* Action / Recap button if available */}
      <div className="flex-row gap-3">
        {event.recapUrl ? (
          <a href={event.recapUrl} className="btn btn-outline btn-sm">
            📸 Recap / Photos
          </a>
        ) : event.url && event.url.startsWith('/') && onNavigate ? (
          <button
            onClick={(e) => onNavigate(event.url!, e)}
            className="btn btn-outline btn-sm"
          >
            View Details
          </button>
        ) : null}
      </div>
    </div>
  );
};
